from datasets import load_dataset
import json

ds = load_dataset("Rtian/DebugBench")["test"]

# 打印 3 条样例
for i in range(3):
    row = ds[i]
    print(f"========== Sample {i+1} ==========")
    for k, v in row.items():
        if isinstance(v, str) and len(v) > 500:
            print(f"  {k}: {v[:500]}... [TRUNCATED, total len={len(v)}]")
        elif isinstance(v, list):
            v_str = json.dumps(v, ensure_ascii=False)
            if len(v_str) > 500:
                print(f"  {k}: {v_str[:500]}... [TRUNCATED, total len={len(v_str)}]")
            else:
                print(f"  {k}: {v_str}")
        else:
            print(f"  {k}: {v}")
    print()
